/**
 * `/projects` 셸 탭 하나의 창(pane) 배치: 오른쪽·아래로 나눈 이진 트리. 잎마다 서버 셸 하나가 붙는다.
 * 첫 잎의 id 는 `ROOT_PANE` 이라 나누기 전 탭의 세션 id 가 그대로 이어진다(이미 도는 셸이 끊기지 않는다).
 * 모든 함수는 새 트리를 돌려준다(상태는 `$state` 에 통째로 다시 넣는다).
 */

/** `n` 은 서버가 매긴 고정 번호(`#프로젝트:n`), `session` 은 그 창의 터미널(master 첫 셸 탭만, 서버가 `#n` 을
 *  풀 때 쓴다). 나눈 직후의 새 잎은 서버가 번호를 줄 때까지 `n` 이 없다(261026 §8). */
export type PaneLeaf = { kind: "leaf"; id: string; n?: number; session?: string };
/** `row` = 왼쪽|오른쪽, `col` = 위/아래. `ratio` 는 `a` 의 몫(0~1). `tail` = 서버가 붙인 창들(`b`)의 뿌리. */
export type PaneSplit = {
	kind: "split";
	dir: "row" | "col";
	ratio: number;
	a: PaneNode;
	b: PaneNode;
	tail?: boolean;
};
export type PaneNode = PaneLeaf | PaneSplit;

export const ROOT_PANE = "root";
export const MIN_RATIO = 0.1;

export const singlePane = (): PaneNode => ({ kind: "leaf", id: ROOT_PANE });

export function leaves(node: PaneNode): PaneLeaf[] {
	return node.kind === "leaf" ? [node] : [...leaves(node.a), ...leaves(node.b)];
}

/** `target` 잎을 둘로 나눠 오른쪽(`row`)·아래(`col`)에 `id` 잎을 둔다. */
export function splitPane(node: PaneNode, target: string, dir: "row" | "col", id: string): PaneNode {
	if (node.kind === "leaf")
		return node.id === target ? { kind: "split", dir, ratio: 0.5, a: node, b: { kind: "leaf", id } } : node;
	return { ...node, a: splitPane(node.a, target, dir, id), b: splitPane(node.b, target, dir, id) };
}

/** 탭 전체를 n×n 격자로 다시 짠다. 기존 잎은 행 우선으로 앞 칸부터 채워 그 셸 · 번호가 이어지고, 남는 칸만
 *  `mint` 가 만든 새 id 를 쓴다. 칸보다 잎이 많으면 뒤쪽은 `dropped` 로 돌려준다(부르는 쪽이 세션을 끝낸다). */
export function gridPane(
	existing: (string | PaneLeaf)[],
	n: number,
	mint: (index: number) => string,
): { panes: PaneNode; dropped: string[] } {
	const cells = n * n;
	const kept = existing.map((leaf): PaneLeaf => (typeof leaf === "string" ? { kind: "leaf", id: leaf } : leaf));
	const used = new Set(kept.map((leaf) => leaf.id));
	const cellsOf = Array.from({ length: cells }, (_, index): PaneLeaf => {
		if (index < kept.length) return kept[index];
		let id = mint(index);
		while (used.has(id)) id += "x";
		used.add(id);
		return { kind: "leaf", id };
	});
	const chain = (nodes: PaneNode[], dir: "row" | "col") =>
		nodes.reduceRight((b, a): PaneNode => ({ kind: "split", dir, ratio: 0.5, a, b }));
	const rows = Array.from({ length: n }, (_, row) => chain(cellsOf.slice(row * n, (row + 1) * n), "row"));
	return { panes: equalize(chain(rows, "col")), dropped: kept.slice(cells).map((leaf) => leaf.id) };
}

/** Agent 창(서버 `workflow/panes.rs`)의 잎 id: `agent3`. 사람이 나눈 잎(`p…`)과 겹치지 않는다. */
export const agentLeaf = (n: number) => `agent${n}`;

export function agentPaneNumber(id: string): number | null {
	const match = /^agent([1-9])$/.exec(id);
	return match ? Number(match[1]) : null;
}

/** worktree 태스크의 Worker TUI 잎 id: `wt-02`. master 첫 셸 탭에서 Agent 창과 같은 열에 선다. */
export const worktreeLeaf = (task: string) => `wt-${task}`;

export function worktreeLeafTask(id: string): string | null {
	return id.startsWith("wt-") ? id.slice(3) : null;
}

/** 서버가 여닫는 잎(Agent 창 · worktree 창). 나머지는 사람이 나눈 창이다. */
export const serverLeaf = (id: string) => agentPaneNumber(id) !== null || worktreeLeafTask(id) !== null;

/** 트리의 번호 붙은 잎들, 번호 순. */
export function numberedLeaves(node: PaneNode): (PaneLeaf & { n: number })[] {
	return leaves(node)
		.filter((leaf): leaf is PaneLeaf & { n: number } => typeof leaf.n === "number")
		.toSorted((a, b) => a.n - b.n);
}

/** 서버가 `#n` 을 풀 수 있게 사람 잎마다 세션을 싣는다(서버 잎의 세션은 서버가 싣는다). */
export function stampSessions(node: PaneNode, sessionOf: (id: string) => string): PaneNode {
	if (node.kind === "leaf")
		return serverLeaf(node.id) || node.session === sessionOf(node.id) ? node : { ...node, session: sessionOf(node.id) };
	return { ...node, a: stampSessions(node.a, sessionOf), b: stampSessions(node.b, sessionOf) };
}

/** `target` 잎을 빼고 형제가 부모 자리를 맡는다. 마지막 잎이면 null(탭을 닫는다). */
export function closePane(node: PaneNode, target: string): PaneNode | null {
	if (node.kind === "leaf") return node.id === target ? null : node;
	const a = closePane(node.a, target);
	const b = closePane(node.b, target);
	if (!a) return b;
	if (!b) return a;
	return { ...node, a, b };
}

